<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model;
class Customer extends Model { protected $fillable=['branch_id','plan_id','sales_user_id','created_by','customer_code','full_name','email','phone','address','service_type','connection_mode','static_ip','mikrotik_router_id','mikrotik_username','due_day','auto_billing','device_serial','odp_port_id','status','installed_at','notes']; protected function casts(): array{return ['due_day'=>'integer','auto_billing'=>'boolean','installed_at'=>'date'];} public function branch(){return $this->belongsTo(Branch::class);} public function plan(){return $this->belongsTo(Plan::class);} public function salesPerson(){return $this->belongsTo(User::class,'sales_user_id');} public function creator(){return $this->belongsTo(User::class,'created_by');} public function userAccount(){return $this->hasOne(User::class);} public function router(){return $this->belongsTo(Router::class,'mikrotik_router_id');} public function odpPort(){return $this->belongsTo(FiberOdpPort::class,'odp_port_id');} public function invoices(){return $this->hasMany(Invoice::class);} public function payments(){return $this->hasMany(Payment::class);} public function serials(){return $this->hasMany(ProductSerial::class);} public function tickets(){return $this->hasMany(MaintenanceTicket::class);} }
